const headers = Object.fromEntries(Object.entries($json.headers ?? {}).map(([key, value]) => [key.toLowerCase(), value]));
const gatewayUser = String(headers['x-alertmanager-user'] ?? '');
const credentialPresent = Object.prototype.hasOwnProperty.call(headers, 'authorization');
const authenticated = gatewayUser === 'wanxiang-alertmanager' && !credentialPresent;
return { json: { AUTHENTICATED: authenticated, body: $json.body ?? null } };

const payload = $json.body ?? {};
const alerts = Array.isArray(payload.alerts) ? payload.alerts : [];
const room = String($env.ALERTMANAGER_MATRIX_ROOM_ID ?? '').trim() || '!GfJXfhwgQXrmCRRjlf:beaco.works';
const linkHosts = new Set(String($env.ALERTMANAGER_LINK_HOSTS ?? 'grafana.beaco.works').split(',').map((host) => host.trim().toLowerCase()).filter(Boolean));
const escapeHtml = (value) => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const secretPatterns = [
  /eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{5,}/g,
  /bearer\s+[A-Za-z0-9._~+/=-]{8,}/gi,
  /(password|passwd|pwd|passkey|token|secret|apikey|api_key|access_key|private_key|authorization|credential)s?\s*[=:]\s*[^\s,;&"']+/gi,
  /[A-Za-z0-9+/]{40,}={0,2}/g,
  /[a-f0-9]{32,}/gi
];
const redact = (value) => {
  let text = String(value);
  for (const pattern of secretPatterns) text = text.replace(pattern, '[redacted]');
  return text;
};
const limit = (value, max) => redact(String(value)).replace(/[\p{Cc}]+/gu, ' ').replace(/\s+/g, ' ').trim().slice(0, max ?? 160);
const safeLink = (raw) => {
  if (typeof raw !== 'string' || raw.length === 0) return '';
  let url;
  try { url = new URL(raw); } catch { return ''; }
  if (url.protocol !== 'https:' && url.protocol !== 'http:') return '';
  if (!linkHosts.has(url.hostname.toLowerCase())) return '';
  return url.origin + url.pathname;
};
const labelKeys = ['severity', 'namespace', 'node', 'pod'];
const render = (input) => {
  const alert = input ?? {};
  const status = alert.status === 'resolved' ? 'resolved' : 'firing';
  const emoji = status === 'resolved' ? '✅' : '🔥';
  const name = limit(String(alert.labels?.alertname ?? 'alert').replace(/[^A-Za-z0-9.:_-]/g, ''), 120);
  const identity = [];
  for (const key of labelKeys) {
    const value = alert.labels?.[key];
    if (typeof value === 'string' && value.trim() !== '') identity.push(key + '=' + limit(value, 80));
  }
  const started = limit(String(alert.startsAt ?? '').slice(0, 16).replace('T', ' '), 32);
  const link = safeLink(alert.generatorURL);
  const notes = ['summary', 'description']
    .map((key) => (typeof alert.annotations?.[key] === 'string' ? limit(alert.annotations[key], 160) : ''))
    .filter(Boolean);
  return { status, emoji, name, identity, started, link, notes };
};
const rows = alerts.slice(0, 20).map(render);
const firing = rows.filter((row) => row.status === 'firing').length;
const resolved = rows.length - firing;
const head = 'Alertmanager: ' + firing + ' firing, ' + resolved + ' resolved' + (alerts.length > rows.length ? ' (of ' + alerts.length + ')' : '');
const htmlRows = rows.map((row) => {
  const identity = row.identity.length ? ' <i>(' + row.identity.map(escapeHtml).join(', ') + ')</i>' : '';
  const link = row.link ? ' · <a href="' + escapeHtml(row.link) + '">details</a>' : '';
  const notes = row.notes.length ? '<br/>' + row.notes.map(escapeHtml).join('<br/>') : '';
  return '<li>' + row.emoji + ' <b>' + escapeHtml(row.name) + '</b>' + identity + '<br/>' + escapeHtml(row.started) + 'Z' + link + notes + '</li>';
}).join('');
const messageHtml = '<b>' + escapeHtml(head) + '</b><ul>' + (htmlRows || '<li>(no alert details)</li>') + '</ul>';
const body = rows.length ? rows.map((row) => {
  const identity = row.identity.length ? ' (' + row.identity.join(', ') + ')' : '';
  const link = row.link ? ' ' + row.link : '';
  const notes = row.notes.length ? '\n  ' + row.notes.join('\n  ') : '';
  return '- ' + row.emoji + ' ' + row.name + identity + '\n  ' + row.started + 'Z' + link + notes;
}).join('\n') : '- (no alert details)';
const messageText = head + '\n' + body;
return { json: { ROOM: room, STATUS: payload.status === 'resolved' ? 'resolved' : 'firing', ALERT_COUNT: alerts.length, FIRING_COUNT: firing, RESOLVED_COUNT: resolved, MESSAGE_HTML: messageHtml, MESSAGE_TEXT: messageText } };
